// Lesson: Linking, Loading, and Stripped Binaries: PLT, GOT, Imports, Fixups, and Function Identification (phase 13 / lesson 40)
// TypeScript port of code/fixtures/build_tiny_dyn_elf.py. Node standard library only.
// Source: phases/13-tools-and-protocols/40-linking-loading-and-stripped-binaries/docs/en.md
// Run: npx tsx phases/13-tools-and-protocols/40-linking-loading-and-stripped-binaries/code/fixtures/build_tiny_dyn_elf.ts

import { statSync, writeFileSync } from "node:fs";
import * as path from "node:path";

const HERE = __dirname;
const OUT = path.join(HERE, "tiny-dyn-x86_64");

const PAGE = 0x1000;
const IMPORTS = ["puts", "exit"];
const NEEDED = "libc.so.6";
const INTERP = Buffer.from("/lib64/ld-linux-x86-64.so.2\0", "latin1");
const MESSAGE = Buffer.from("linked by hand\0", "latin1");

const PT_LOAD = 1;
const PT_DYNAMIC = 2;
const PT_INTERP = 3;
const PF_X = 1;
const PF_W = 2;
const PF_R = 4;
const SHT_PROGBITS = 1;
const SHT_STRTAB = 3;
const SHT_RELA = 4;
const SHT_HASH = 5;
const SHT_DYNAMIC = 6;
const SHT_DYNSYM = 11;
const SHF_WRITE = 0x1;
const SHF_ALLOC = 0x2;
const SHF_EXECINSTR = 0x4;
const SHF_INFO_LINK = 0x40;
const R_X86_64_JUMP_SLOT = 7;
const DT_NULL = 0;
const DT_NEEDED = 1;
const DT_PLTRELSZ = 2;
const DT_PLTGOT = 3;
const DT_HASH = 4;
const DT_STRTAB = 5;
const DT_SYMTAB = 6;
const DT_STRSZ = 10;
const DT_SYMENT = 11;
const DT_PLTREL = 20;
const DT_JMPREL = 23;
const DT_RELA = 7;
const DT_FLAGS_1 = 0x6ffffffb;
const DF_1_PIE = 0x08000000;

type Value = number | bigint | Buffer;

function packInto(format: string, buffer: Buffer, offset: number, ...values: Value[]): number {
  let cursor = offset;
  let next = 0;
  for (const [, countText, code] of format.slice(1).matchAll(/(\d*)([sBbHhIiQq])/g)) {
    const count = countText === "" ? 1 : parseInt(countText, 10);
    if (code === "s") {
      const raw = values[next++] as Buffer;
      buffer.fill(0, cursor, cursor + count);
      raw.copy(buffer, cursor, 0, Math.min(count, raw.length));
      cursor += count;
      continue;
    }
    for (let k = 0; k < count; k++) {
      const value = values[next++] as number | bigint;
      if (code === "B") cursor = buffer.writeUInt8(Number(value), cursor);
      else if (code === "b") cursor = buffer.writeInt8(Number(value), cursor);
      else if (code === "H") cursor = buffer.writeUInt16LE(Number(value), cursor);
      else if (code === "h") cursor = buffer.writeInt16LE(Number(value), cursor);
      else if (code === "I") cursor = buffer.writeUInt32LE(Number(value), cursor);
      else if (code === "i") cursor = buffer.writeInt32LE(Number(value), cursor);
      else if (code === "Q") cursor = buffer.writeBigUInt64LE(BigInt(value), cursor);
      else cursor = buffer.writeBigInt64LE(BigInt(value), cursor);
    }
  }
  return cursor - offset;
}

function pack(format: string, ...values: Value[]): Buffer {
  const scratch = Buffer.alloc(4096);
  return Buffer.from(scratch.subarray(0, packInto(format, scratch, 0, ...values)));
}

function bytes(...values: number[]): Buffer {
  return Buffer.from(values);
}

export function align(value: number, boundary: number): number {
  return (value + boundary - 1) & ~(boundary - 1);
}

export function sysvHash(name: string): number {
  let h = 0;
  for (const c of Buffer.from(name, "utf8")) {
    h = h * 16 + c;
    const g = (h & 0xf0000000) >>> 0;
    if (g) h = (h ^ (g >>> 24)) >>> 0;
    h = (h & ~g & 0xffffffff) >>> 0;
  }
  return h;
}

export function rel32(target: number, nextInstruction: number): Buffer {
  return pack("<i", target - nextInstruction);
}

export function build(): Buffer {
  const phnum = 4;
  const interpOff = 64 + 56 * phnum;
  const dynsymOff = align(interpOff + INTERP.length, 8);
  const dynsymSize = 24 * (1 + IMPORTS.length);
  const dynstrOff = dynsymOff + dynsymSize;
  let dynstr = Buffer.from([0]);
  const nameOffset = new Map<string, number>();
  for (const name of [...IMPORTS, NEEDED]) {
    nameOffset.set(name, dynstr.length);
    dynstr = Buffer.concat([dynstr, Buffer.from(name, "utf8"), bytes(0)]);
  }
  const hashOff = align(dynstrOff + dynstr.length, 8);
  const hashSize = 8 + 4 * 1 + 4 * (1 + IMPORTS.length);
  const relapltOff = align(hashOff + hashSize, 8);
  const relapltSize = 24 * IMPORTS.length;
  const pltOff = align(relapltOff + relapltSize, 16);
  const pltSize = 16 * (1 + IMPORTS.length);
  const textOff = pltOff + pltSize;
  const codeSize = 7 + 5 + 2 + 5 + 1;
  const rodataOff = align(textOff + codeSize, 8);
  const rxEnd = rodataOff + MESSAGE.length;
  const dynamicOff = PAGE;
  const dynamicCount = 12;
  const dynamicSize = 16 * dynamicCount;
  const gotpltOff = dynamicOff + dynamicSize;
  const gotpltSize = 8 * (3 + IMPORTS.length);
  const rwEnd = gotpltOff + gotpltSize;
  const sectionNames = [".interp", ".dynsym", ".dynstr", ".hash", ".rela.plt", ".plt", ".text", ".rodata", ".dynamic", ".got.plt", ".shstrtab"];
  let shstrtab = Buffer.from([0]);
  const shname = new Map<string, number>();
  for (const name of sectionNames) {
    shname.set(name, shstrtab.length);
    shstrtab = Buffer.concat([shstrtab, Buffer.from(name, "utf8"), bytes(0)]);
  }
  const shstrtabOff = rwEnd;
  const shoff = align(shstrtabOff + shstrtab.length, 8);
  const shnum = 1 + sectionNames.length;
  const image = Buffer.alloc(shoff + 64 * shnum);

  const pltEntry = (index: number): number => pltOff + 16 * (index + 1);
  const gotSlot = (index: number): number => gotpltOff + 24 + 8 * index;

  packInto("<16sHHIQQQIHHHHHH", image, 0, Buffer.concat([bytes(0x7f, 0x45, 0x4c, 0x46, 0x02, 0x01, 0x01, 0x00), Buffer.alloc(8)]), 3, 62, 1, textOff, 64, shoff, 0, 64, 56, phnum, 64, shnum, shnum - 1);
  const phdrs: [number, number, number, number, number][] = [
    [PT_INTERP, PF_R, interpOff, INTERP.length, 1],
    [PT_LOAD, PF_R | PF_X, 0, rxEnd, PAGE],
    [PT_LOAD, PF_R | PF_W, PAGE, rwEnd - PAGE, PAGE],
    [PT_DYNAMIC, PF_R | PF_W, dynamicOff, dynamicSize, 8],
  ];
  phdrs.forEach(([pType, flags, offset, size, pAlign], index) => {
    packInto("<IIQQQQQQ", image, 64 + 56 * index, pType, flags, offset, offset, offset, size, size, pAlign);
  });
  INTERP.copy(image, interpOff);
  IMPORTS.forEach((name, k) => {
    packInto("<IBBHQQ", image, dynsymOff + 24 * (k + 1), nameOffset.get(name) ?? 0, 0x12, 0, 0, 0, 0);
  });
  dynstr.copy(image, dynstrOff);
  const nchain = 1 + IMPORTS.length;
  const chain: number[] = new Array(nchain).fill(0);
  let bucket = 0;
  for (let index = 1; index < nchain; index++) {
    chain[index] = bucket;
    bucket = index;
  }
  packInto(`<II${1}I${nchain}I`, image, hashOff, 1, nchain, bucket, ...chain);
  for (let index = 0; index < IMPORTS.length; index++) {
    packInto("<QQq", image, relapltOff + 24 * index, gotSlot(index), (BigInt(index + 1) << 32n) | BigInt(R_X86_64_JUMP_SLOT), 0);
  }
  const plt0 = Buffer.concat([bytes(0xff, 0x35), rel32(gotpltOff + 8, pltOff + 6), bytes(0xff, 0x25), rel32(gotpltOff + 16, pltOff + 12), bytes(0x0f, 0x1f, 0x40, 0x00)]);
  plt0.copy(image, pltOff);
  for (let index = 0; index < IMPORTS.length; index++) {
    const entry = pltEntry(index);
    const body = Buffer.concat([bytes(0xff, 0x25), rel32(gotSlot(index), entry + 6), bytes(0x68), pack("<I", index), bytes(0xe9), rel32(pltOff, entry + 16)]);
    body.copy(image, entry);
  }
  const code = Buffer.concat([
    bytes(0x48, 0x8d, 0x3d), rel32(rodataOff, textOff + 7),
    bytes(0xe8), rel32(pltEntry(0), textOff + 12),
    bytes(0x31, 0xff),
    bytes(0xe8), rel32(pltEntry(1), textOff + 19),
    bytes(0xf4),
  ]);
  if (code.length !== codeSize) throw new Error("assertion failed: code size");
  code.copy(image, textOff);
  MESSAGE.copy(image, rodataOff);
  const dynamic: [number, number][] = [
    [DT_NEEDED, nameOffset.get(NEEDED) ?? 0],
    [DT_HASH, hashOff],
    [DT_STRTAB, dynstrOff],
    [DT_SYMTAB, dynsymOff],
    [DT_STRSZ, dynstr.length],
    [DT_SYMENT, 24],
    [DT_PLTGOT, gotpltOff],
    [DT_PLTRELSZ, relapltSize],
    [DT_PLTREL, DT_RELA],
    [DT_JMPREL, relapltOff],
    [DT_FLAGS_1, DF_1_PIE],
    [DT_NULL, 0],
  ];
  if (dynamic.length !== dynamicCount) throw new Error("assertion failed: dynamic count");
  dynamic.forEach(([tag, value], index) => {
    packInto("<qQ", image, dynamicOff + 16 * index, tag, value);
  });
  const got = [dynamicOff, 0, 0, ...IMPORTS.map((_, index) => pltEntry(index) + 6)];
  packInto(`<${got.length}Q`, image, gotpltOff, ...got);
  shstrtab.copy(image, shstrtabOff);
  const dynsymIndex = 2;
  const dynstrIndex = 3;
  const gotpltIndex = 10;
  const sections: [string, number, number, number, number, number, number, number, number][] = [
    [".interp", SHT_PROGBITS, SHF_ALLOC, interpOff, INTERP.length, 0, 0, 1, 0],
    [".dynsym", SHT_DYNSYM, SHF_ALLOC, dynsymOff, dynsymSize, dynstrIndex, 1, 8, 24],
    [".dynstr", SHT_STRTAB, SHF_ALLOC, dynstrOff, dynstr.length, 0, 0, 1, 0],
    [".hash", SHT_HASH, SHF_ALLOC, hashOff, hashSize, dynsymIndex, 0, 8, 4],
    [".rela.plt", SHT_RELA, SHF_ALLOC | SHF_INFO_LINK, relapltOff, relapltSize, dynsymIndex, gotpltIndex, 8, 24],
    [".plt", SHT_PROGBITS, SHF_ALLOC | SHF_EXECINSTR, pltOff, pltSize, 0, 0, 16, 16],
    [".text", SHT_PROGBITS, SHF_ALLOC | SHF_EXECINSTR, textOff, codeSize, 0, 0, 16, 0],
    [".rodata", SHT_PROGBITS, SHF_ALLOC, rodataOff, MESSAGE.length, 0, 0, 1, 0],
    [".dynamic", SHT_DYNAMIC, SHF_ALLOC | SHF_WRITE, dynamicOff, dynamicSize, dynstrIndex, 0, 8, 16],
    [".got.plt", SHT_PROGBITS, SHF_ALLOC | SHF_WRITE, gotpltOff, gotpltSize, 0, 0, 8, 8],
    [".shstrtab", SHT_STRTAB, 0, shstrtabOff, shstrtab.length, 0, 0, 1, 0],
  ];
  sections.forEach(([name, shType, flags, offset, size, link, info, shAlign, entsize], k) => {
    const addr = flags === 0 ? 0 : offset;
    packInto("<IIQQQQIIQQ", image, shoff + 64 * (k + 1), shname.get(name) ?? 0, shType, flags, addr, offset, size, link, info, shAlign, entsize);
  });
  return image;
}

if (require.main === module) {
  writeFileSync(OUT, build());
  console.log(`wrote ${path.basename(OUT)}: ${statSync(OUT).size} bytes`);
}

// Lesson: Linking, Loading, and Stripped Binaries: PLT, GOT, Imports, Fixups, and Function Identification (phase 13 / lesson 40)
// TypeScript port of code/fixtures/build_tiny_pe.py. Node standard library only.
// Source: phases/13-tools-and-protocols/40-linking-loading-and-stripped-binaries/docs/en.md
// Run: npx tsx phases/13-tools-and-protocols/40-linking-loading-and-stripped-binaries/code/fixtures/build_tiny_pe.ts

import { statSync, writeFileSync } from "node:fs";
import * as path from "node:path";

const HERE = __dirname;
const OUT = path.join(HERE, "tiny-x86_64.exe");

const IMAGE_BASE = 0x140000000;
const FILE_ALIGN = 0x200;
const SECTION_ALIGN = 0x1000;
const DLL = Buffer.from("msvcrt.dll\0", "latin1");
const IMPORTS = ["puts", "exit"];
const MESSAGE = Buffer.from("linked by hand\0", "latin1");
const EXPORT_NAME = Buffer.from("tiny_entry\0", "latin1");
const IMAGE_NAME = Buffer.from("tiny-x86_64.exe\0", "latin1");

const IMAGE_FILE_MACHINE_AMD64 = 0x8664;
const IMAGE_FILE_EXECUTABLE_IMAGE = 0x0002;
const IMAGE_FILE_LARGE_ADDRESS_AWARE = 0x0020;
const PE32_PLUS = 0x20b;
const SUBSYSTEM_CUI = 3;
const DLL_HIGH_ENTROPY_VA = 0x0020;
const DLL_DYNAMIC_BASE = 0x0040;
const DLL_NX_COMPAT = 0x0100;
const DLL_TERMINAL_SERVER_AWARE = 0x8000;
const SCN_CODE = 0x00000020;
const SCN_INITIALIZED_DATA = 0x00000040;
const SCN_MEM_DISCARDABLE = 0x02000000;
const SCN_MEM_EXECUTE = 0x20000000;
const SCN_MEM_READ = 0x40000000;
const SCN_MEM_WRITE = 0x80000000;
const IMAGE_REL_BASED_DIR64 = 10;
const DIR_EXPORT = 0;
const DIR_IMPORT = 1;
const DIR_BASERELOC = 5;
const DIR_IAT = 12;

type Value = number | bigint | Buffer;

function packInto(format: string, buffer: Buffer, offset: number, ...values: Value[]): number {
  let cursor = offset;
  let next = 0;
  for (const [, countText, code] of format.slice(1).matchAll(/(\d*)([sBbHhIiQq])/g)) {
    const count = countText === "" ? 1 : parseInt(countText, 10);
    if (code === "s") {
      const raw = values[next++] as Buffer;
      buffer.fill(0, cursor, cursor + count);
      raw.copy(buffer, cursor, 0, Math.min(count, raw.length));
      cursor += count;
      continue;
    }
    for (let k = 0; k < count; k++) {
      const value = values[next++] as number | bigint;
      if (code === "B") cursor = buffer.writeUInt8(Number(value), cursor);
      else if (code === "b") cursor = buffer.writeInt8(Number(value), cursor);
      else if (code === "H") cursor = buffer.writeUInt16LE(Number(value), cursor);
      else if (code === "h") cursor = buffer.writeInt16LE(Number(value), cursor);
      else if (code === "I") cursor = buffer.writeUInt32LE(Number(value), cursor);
      else if (code === "i") cursor = buffer.writeInt32LE(Number(value), cursor);
      else if (code === "Q") cursor = buffer.writeBigUInt64LE(BigInt(value), cursor);
      else cursor = buffer.writeBigInt64LE(BigInt(value), cursor);
    }
  }
  return cursor - offset;
}

function pack(format: string, ...values: Value[]): Buffer {
  const scratch = Buffer.alloc(4096);
  return Buffer.from(scratch.subarray(0, packInto(format, scratch, 0, ...values)));
}

function bytes(...values: number[]): Buffer {
  return Buffer.from(values);
}

export function rel32(targetRva: number, nextRva: number): Buffer {
  return pack("<i", targetRva - nextRva);
}

export function padded(blob: Buffer, size: number): Buffer {
  return Buffer.concat([blob, Buffer.alloc(size - blob.length)]);
}

export function build(): Buffer {
  const [textRva, rdataRva, dataRva, relocRva] = [0x1000, 0x2000, 0x3000, 0x4000];
  const [textOff, rdataOff, dataOff, relocOff] = [0x200, 0x400, 0x600, 0x800];

  const descriptorRva = rdataRva;
  const iltRva = rdataRva + 0x28;
  const iatRva = rdataRva + 0x40;
  const hintRva = new Map<string, number>([[IMPORTS[0], rdataRva + 0x58], [IMPORTS[1], rdataRva + 0x60]]);
  const dllRva = rdataRva + 0x68;
  const exportDirRva = rdataRva + 0x80;
  const eatRva = exportDirRva + 40;
  const enptRva = eatRva + 4;
  const eotRva = enptRva + 4;
  const imageNameRva = eotRva + 2;
  const exportNameRva = imageNameRva + IMAGE_NAME.length;
  const messageRva = exportNameRva + EXPORT_NAME.length;
  const exportSize = messageRva - exportDirRva;

  const code = Buffer.concat([
    bytes(0x48, 0x83, 0xec, 0x28),
    bytes(0x48, 0x8d, 0x0d), rel32(messageRva, textRva + 11),
    bytes(0xff, 0x15), rel32(iatRva, textRva + 17),
    bytes(0x31, 0xc9),
    bytes(0xff, 0x15), rel32(iatRva + 8, textRva + 25),
    bytes(0xcc),
  ]);

  const rdata = Buffer.alloc(0x200);
  packInto("<IIIII", rdata, 0, iltRva, 0, 0, dllRva, iatRva);
  const thunks = pack("<QQQ", hintRva.get(IMPORTS[0]) ?? 0, hintRva.get(IMPORTS[1]) ?? 0, 0);
  thunks.copy(rdata, 0x28);
  thunks.copy(rdata, 0x40);
  padded(Buffer.concat([bytes(0, 0), Buffer.from(IMPORTS[0], "utf8"), bytes(0)]), 8).copy(rdata, 0x58);
  padded(Buffer.concat([bytes(0, 0), Buffer.from(IMPORTS[1], "utf8"), bytes(0)]), 8).copy(rdata, 0x60);
  DLL.copy(rdata, 0x68);
  packInto("<IIHHIIIIIII", rdata, 0x80, 0, 0, 0, 0, imageNameRva, 1, 1, 1, eatRva, enptRva, eotRva);
  packInto("<I", rdata, eatRva - rdataRva, textRva);
  packInto("<I", rdata, enptRva - rdataRva, exportNameRva);
  packInto("<H", rdata, eotRva - rdataRva, 0);
  IMAGE_NAME.copy(rdata, imageNameRva - rdataRva);
  EXPORT_NAME.copy(rdata, exportNameRva - rdataRva);
  MESSAGE.copy(rdata, messageRva - rdataRva);
  const rdataUsed = messageRva - rdataRva + MESSAGE.length;

  const data = pack("<Q", IMAGE_BASE + messageRva);
  const reloc = pack("<IIHH", dataRva, 12, (IMAGE_REL_BASED_DIR64 << 12) | 0, 0);

  const sections: [Buffer, number, number, number, number][] = [
    [Buffer.from(".text"), code.length, textRva, textOff, SCN_CODE | SCN_MEM_EXECUTE | SCN_MEM_READ],
    [Buffer.from(".rdata"), rdataUsed, rdataRva, rdataOff, SCN_INITIALIZED_DATA | SCN_MEM_READ],
    [Buffer.from(".data"), data.length, dataRva, dataOff, (SCN_INITIALIZED_DATA | SCN_MEM_READ | SCN_MEM_WRITE) >>> 0],
    [Buffer.from(".reloc"), reloc.length, relocRva, relocOff, SCN_INITIALIZED_DATA | SCN_MEM_READ | SCN_MEM_DISCARDABLE],
  ];

  const image = Buffer.alloc(relocOff + FILE_ALIGN);
  bytes(0x4d, 0x5a).copy(image, 0);
  packInto("<I", image, 0x3c, 0x40);
  bytes(0x50, 0x45, 0, 0).copy(image, 0x40);
  packInto("<HHIIIHH", image, 0x44, IMAGE_FILE_MACHINE_AMD64, sections.length, 0, 0, 0, 240, IMAGE_FILE_EXECUTABLE_IMAGE | IMAGE_FILE_LARGE_ADDRESS_AWARE);
  packInto(
    "<HBBIIIIIQIIHHHHHHIIIIHHQQQQII", image, 0x58,
    PE32_PLUS, 14, 0, FILE_ALIGN, 3 * FILE_ALIGN, 0, textRva, textRva, IMAGE_BASE, SECTION_ALIGN, FILE_ALIGN,
    6, 0, 0, 0, 6, 0, 0, 0x5000, 0x200, 0, SUBSYSTEM_CUI,
    DLL_HIGH_ENTROPY_VA | DLL_DYNAMIC_BASE | DLL_NX_COMPAT | DLL_TERMINAL_SERVER_AWARE,
    0x100000, 0x1000, 0x100000, 0x1000, 0, 16,
  );
  const directories = 0x58 + 112;
  packInto("<II", image, directories + 8 * DIR_EXPORT, exportDirRva, exportSize);
  packInto("<II", image, directories + 8 * DIR_IMPORT, descriptorRva, 40);
  packInto("<II", image, directories + 8 * DIR_BASERELOC, relocRva, reloc.length);
  packInto("<II", image, directories + 8 * DIR_IAT, iatRva, 24);
  const table = directories + 16 * 8;
  sections.forEach(([name, virtualSize, rva, offset, characteristics], index) => {
    packInto("<8sIIIIIIHHI", image, table + 40 * index, name, virtualSize, rva, FILE_ALIGN, offset, 0, 0, 0, 0, characteristics);
  });
  code.copy(image, textOff);
  rdata.copy(image, rdataOff);
  data.copy(image, dataOff);
  reloc.copy(image, relocOff);
  return image;
}

if (require.main === module) {
  writeFileSync(OUT, build());
  console.log(`wrote ${path.basename(OUT)}: ${statSync(OUT).size} bytes`);
}

int percent_change(int before, int after) {
    if (before == 0) return 0;
    return (after - before) * 100 / before;
}

int grade(int score) {
    switch (score / 10) {
    case 10:
    case 9: return 4;
    case 8: return 3;
    case 7: return 2;
    case 6: return 1;
    default: return 0;
    }
}

int total(const int *values, int count) {
    int sum = 0;
    for (int i = 0; i < count; i++) sum += values[i];
    return sum;
}

static const char *labels[] = { "F", "D", "C", "B", "A" };

const char *grade_label(int score) {
    return labels[grade(score)];
}

int percent_change(int before, int after);
int grade(int score);
int total(const int *values, int count);
const char *grade_label(int score);
int printf(const char *fmt, ...);
int puts(const char *s);

static const char *const names[] = { "even", "odd" };
int (*const fns[])(int) = { grade, grade };

int main(int argc, char **argv) {
    int v[] = { 1, 2, 3, 4 };
    (void)argv;
    puts(names[argc & 1]);
    printf("%d\n", fns[argc & 1](72));
    printf("%d %d %d %s\n", percent_change(100, 150), grade(85), total(v, 4), grade_label(85));
    if (argc > 1) puts("args");
    return 0;
}

"""Companion code for docs/en.md: read what the link editor made and what the loader will do.
ELF: gABI chapter 5 (dynamic section, program headers), x86-64 psABI section 5.2 (GOT, PLT, lazy binding) and Table 4.9.
PE/COFF: Microsoft PE Format (file header, section table, 18-byte symbols, 10-byte relocations, import and export directories, base relocations).
Mach-O: loader.h, nlist.h and fixup-chains.h (load commands, stubs, indirect symbols, chained fixups, exports trie, two-level namespace).
Function identification: LC_FUNCTION_STARTS, prologue patterns, call targets, and a FLIRT-shaped signature with wildcarded relocation bytes.
Run `python3 main.py` for the finite demo or `python3 tests/test_main.py` for the suite.
"""

from __future__ import annotations

import json
import struct
import sys
from dataclasses import dataclass, field
from pathlib import Path
from typing import Any

HERE = Path(__file__).resolve().parent
FIXTURES = HERE / "fixtures"


class FormatError(ValueError):
    pass


def _cstring(table: bytes, offset: int) -> str:
    end = table.find(b"\0", offset)
    return table[offset : end if end >= 0 else len(table)].decode("utf-8", "replace")


def _hex(value: int) -> str:
    return f"0x{value:x}"


def read_uleb128(data: bytes, offset: int) -> tuple[int, int]:
    value = 0
    shift = 0
    while True:
        byte = data[offset]
        offset += 1
        value |= (byte & 0x7F) << shift
        shift += 7
        if not byte & 0x80:
            return value, offset


def crc16(data: bytes) -> int:
    """The CRC-16 that the public .pat parsers use: polynomial 0x8408 (reflected 0x1021), initial 0xFFFF, final complement and byte swap."""
    if not data:
        return 0
    crc = 0xFFFF
    for byte in data:
        for _ in range(8):
            if (crc ^ byte) & 1:
                crc = (crc >> 1) ^ 0x8408
            else:
                crc >>= 1
            byte >>= 1
    crc = ~crc & 0xFFFF
    return ((crc << 8) | (crc >> 8)) & 0xFFFF


def _hexbytes(data: bytes) -> str:
    return " ".join(f"{byte:02x}" for byte in data)


def _signed(value: int, bits: int) -> int:
    return value - (1 << bits) if value & (1 << (bits - 1)) else value


