                    })
                    .collect(),
            ),
        )
        .with(
            "symbols",
            J::Arr(
                coff.symbols
                    .iter()
                    .map(|x| {
                        J::obj()
                            .with("index", int(x.index))
                            .with("name", s(&x.name))
